952	// =========================================================================
953	//  Forward kernel 2: CSA/HCA sequence mixing — implemented as the
954	//  sg::sm90::csa_hca kernels above (csa/hca compress + attention). The
955	//  orchestration launchers below stitch them together. The old Mamba-3
956	//  scan kernel (sg2_mamba3_scan_kernel) was removed in the CSA/HCA port.
957	// =========================================================================
958	
959	// =========================================================================
960	//  Forward kernel 3 + 4: GRU + PEER + apply tail
961	//  PEER routing's gather/scatter happens in host code; this kernel
962	//  consumes the routed expert output and runs GRU + smart_grad + Adam.
963	// =========================================================================
964	
965	template <typename ParamT, typename GradT>
966	__global__ void sg2_apply_kernel(
967	    ParamT* param, float* exp_avg, float* exp_avg_sq, float* mu_state,
968	    float* slow_state,
969	    const GradT* grad, const float* expert_out,
970	    float alpha, float gru_decay, float lamb_eff,
971	    float lr, float beta1, float beta2, float eps, float wd,
972	    float bc1, float bc2, int64_t N
973	) {
974	    const int64_t stride = prim::grid_stride();
975	    for (int64_t i = prim::grid_stride_index(); i < N; i += stride) {
976	        ::sg::algorithms::sg2_apply_step(
977	            param, exp_avg, exp_avg_sq, mu_state, slow_state, grad,
978	            expert_out[i], alpha, gru_decay, lamb_eff,
979	            lr, beta1, beta2, eps, wd, bc1, bc2, i);
980	    }
981	}
982	
983	// =========================================================================
984	//  Host-side launchers
985	// =========================================================================
