987	void launch_supergrok2_input_proj_sort(
988	    const torch::Tensor& grad, const torch::Tensor& sharpness,
989	    torch::Tensor& x_out, torch::Tensor& sort_keys, torch::Tensor& sort_indices,
990	    const torch::Tensor& proj_W, const torch::Tensor& proj_b
991	) {
992	    const int64_t N = grad.numel();
993	    const int d_model = proj_W.size(0);
994	    auto stream = at::cuda::getCurrentCUDAStream().stream();
995	    const int block = SG_TUNED_BLOCK_SIZE;
996	    // One element per thread (no grid-stride loop in this kernel): grid must
997	    // cover all N. Form the division in int64 then cast the (in-range) grid dim.
998	    const int grid = static_cast<int>((N + block - 1) / block);
999	
1000	    const bool wt_bf16 = (proj_W.scalar_type() == at::ScalarType::BFloat16);
1001	    AT_DISPATCH_FLOATING_TYPES_AND2(
1002	        at::ScalarType::Half, at::ScalarType::BFloat16,
1003	        grad.scalar_type(), "sg2_input_proj_sort", [&] {
1004	            if (wt_bf16) {
1005	                sg2_input_proj_sort_kernel<scalar_t, at::BFloat16><<<grid, block, 0, stream>>>(
1006	                    grad.data_ptr<scalar_t>(),
1007	                    sharpness.data_ptr<scalar_t>(),
1008	                    x_out.data_ptr<float>(),
1009	                    sort_keys.data_ptr<float>(),
1010	                    sort_indices.data_ptr<int>(),
1011	                    proj_W.data_ptr<at::BFloat16>(),
1012	                    proj_b.data_ptr<at::BFloat16>(),
1013	                    N, d_model);
1014	            } else {
1015	                sg2_input_proj_sort_kernel<scalar_t, float><<<grid, block, 0, stream>>>(
1016	                    grad.data_ptr<scalar_t>(),
1017	                    sharpness.data_ptr<scalar_t>(),
1018	                    x_out.data_ptr<float>(),
1019	                    sort_keys.data_ptr<float>(),
1020	                    sort_indices.data_ptr<int>(),
1021	                    proj_W.data_ptr<float>(),
1022	                    proj_b.data_ptr<float>(),
1023	                    N, d_model);
1024	            }
1025	            SG_LAUNCH_CHECK(stream);
1026	        });
1027	}
