1029	void launch_supergrok2_apply(
1030	    torch::Tensor& param, torch::Tensor& exp_avg, torch::Tensor& exp_avg_sq,
1031	    torch::Tensor& mu_state, torch::Tensor& slow_state,
1032	    const torch::Tensor& grad,
1033	    const torch::Tensor& expert_out,
1034	    float alpha, float gru_decay, float lamb_eff,
1035	    float lr, float beta1, float beta2, float eps, float wd,
1036	    float bc1, float bc2
1037	) {
1038	    const int64_t N = param.numel();
1039	    if (N == 0) return;
1040	    auto stream = at::cuda::getCurrentCUDAStream().stream();
1041	    const int block = SG_TUNED_BLOCK_SIZE;
1042	    // #9 int-width: clamp the grid in int64 (N is int64; the (N+block-1)/block
1043	    // ceil-div can exceed 2^31 before the 65535 cap) then narrow the grid dim to
1044	    // int — matches the grokadamw/adamw launcher idiom.
1045	    const int grid = static_cast<int>(
1046	        std::min<int64_t>(65535, (N + block - 1) / block));
1047	
1048	    AT_DISPATCH_FLOATING_TYPES_AND2(
1049	        at::ScalarType::Half, at::ScalarType::BFloat16,
1050	        param.scalar_type(), "sg2_apply", [&] {
1051	            sg2_apply_kernel<scalar_t, scalar_t><<<grid, block, 0, stream>>>(
1052	                param.data_ptr<scalar_t>(),
1053	                exp_avg.data_ptr<float>(),
1054	                exp_avg_sq.data_ptr<float>(),
1055	                mu_state.data_ptr<float>(),
1056	                slow_state.data_ptr<float>(),
1057	                grad.data_ptr<scalar_t>(),
1058	                expert_out.data_ptr<float>(),
1059	                alpha, gru_decay, lamb_eff,
1060	                lr, beta1, beta2, eps, wd, bc1, bc2, N);
1061	            SG_LAUNCH_CHECK(stream);
1062	        });
1063	}
