1065	// ═════════════════════════════════════════════════════════════════════════
1066	//  MoE/Adam multi-tensor — folded in from former launch_moe_adam.cu.
1067	//
1068	//  For Mixture-of-Experts models, this launcher accepts a packed buffer
1069	//  containing only the active subset of expert parameters. The caller is
1070	//  responsible for gathering active parameters before the call and
1071	//  scattering results after. Otherwise this is identical to AdamW.
1072	//  The per-element math lives in supergrok2.h::moe_adam_step (which
1073	//  re-exports adamw.h::adamw_step).
1074	// ═════════════════════════════════════════════════════════════════════════
1075	
1076	using ::sg::algorithms::moe_adam_step;
1077	
1078	template <typename ParamT, typename GradT>
1079	__global__ void moe_adam_kernel(
1080	    ParamT* param, float* exp_avg, float* exp_avg_sq,
1081	    const GradT* grad,
1082	    float lr, float beta1, float beta2, float eps, float wd,
1083	    float bc1, float bc2, int64_t N
1084	) {
1085	    const int64_t stride = prim::grid_stride();
1086	    for (int64_t i = prim::grid_stride_index(); i < N; i += stride) {
1087	        moe_adam_step(param, exp_avg, exp_avg_sq, grad,
1088	                      lr, beta1, beta2, eps, wd, bc1, bc2, i);
1089	    }
1090	}
1091	
1092	void launch_moe_adam_step(
1093	    torch::Tensor& param,
1094	    torch::Tensor& exp_avg,
1095	    torch::Tensor& exp_avg_sq,
1096	    const torch::Tensor& grad,
1097	    float lr, float beta1, float beta2, float eps, float wd,
1098	    float bc1, float bc2
1099	) {
1100	    const int64_t N = param.numel();
1101	    if (N == 0) return;
1102	
1103	    auto stream = at::cuda::getCurrentCUDAStream().stream();
1104	    const int block = SG_TUNED_BLOCK_SIZE;
1105	    const int grid = std::min<int>(65535, (N + block - 1) / block);
1106	
1107	    AT_DISPATCH_FLOATING_TYPES_AND2(
1108	        at::ScalarType::Half, at::ScalarType::BFloat16,
1109	        param.scalar_type(), "moe_adam_step", [&] {
1110	            moe_adam_kernel<scalar_t, scalar_t><<<grid, block, 0, stream>>>(
1111	                param.data_ptr<scalar_t>(),
1112	                exp_avg.data_ptr<float>(),
1113	                exp_avg_sq.data_ptr<float>(),
1114	                grad.data_ptr<scalar_t>(),
1115	                lr, beta1, beta2, eps, wd, bc1, bc2, N);
1116	            SG_LAUNCH_CHECK(stream);
1117	        });
1118	}
