1120	// ═════════════════════════════════════════════════════════════════════════
1121	//  GRU step kernel (per-element MiniGRU integrating the attention contexts).
1122	//
1123	//  Kept verbatim contract from the pre-CSA/HCA tail (spec §3b): the GRU state
1124	//  is carried across optimizer steps. Here we run a lightweight per-element
1125	//  gated update of the carried gru_state with the meta-model candidate as the
1126	//  candidate activation; the full matrix GRU gates are applied on the
1127	//  host-side projection (ATen) and this kernel finalizes the elementwise
1128	//  blend, matching sg2_apply_step's mu update convention.
1129	// ═════════════════════════════════════════════════════════════════════════
1130	
1131	__global__ void sg2_gru_blend_kernel(
1132	    float* __restrict__ gru_state,          // [N] carried state (in/out)
1133	    const float* __restrict__ candidate,    // [N] candidate (expert/attn output)
1134	    const float* __restrict__ z_gate,       // [N] update gate in [0,1] or nullptr
1135	    float* __restrict__ out,                // [N] new gru output
1136	    float gru_decay, int64_t N
1137	) {
1138	    // #9 int-width: mirror the other SG2 element-wise kernels — the index/stride
1139	    // are int64 (grid_stride()/grid_stride_index() return int64_t) so a launch
1140	    // covering >2^31 elements cannot truncate the global index.
1141	    const int64_t stride = prim::grid_stride();
1142	    for (int64_t i = prim::grid_stride_index(); i < N; i += stride) {
1143	        const float z = (z_gate != nullptr) ? z_gate[i] : gru_decay;
1144	        const float h = z * gru_state[i] + (1.0f - z) * candidate[i];
1145	        gru_state[i] = h;
1146	        out[i] = h;
1147	    }
1148	}
1149	
1150	// ═════════════════════════════════════════════════════════════════════════
1151	//  CSA/HCA meta-model forward (single parameter tensor).
1152	//
1153	//  Implements the spec §3b pipeline for one flattened parameter:
1154	//    input_proj_sort -> CSA compress+indexer top-k+attention (csa_ctx)
1155	//                    -> HCA compress+dense attention (hca_ctx)
1156	//                    -> GRU blend -> PEER routing + expert MLP -> expert_out
1157	//  then returns expert_out (unsorted, [N]) for the Adam apply tail.
1158	//
1159	//  Attention runs through the custom sg::sm90::csa_hca kernels; the small
1160	//  projections / PEER routing use ATen ops (cuBLAS / CUTLASS-backed mm) so
1161	//  the path is fully functional regardless of WITH_CUTLASS.
1162	// ═════════════════════════════════════════════════════════════════════════
1163	
1164	namespace detail {
1165	
1166	// Strided weighted-pool + project a sorted sequence into compressed K/V.
1167	// proj_W may be float or bf16 (bandwidth win via wt_t template dispatch).
1168	static torch::Tensor compress_csa(
1169	    const torch::Tensor& x_sorted_f32,      // [N, d_model] (float, cuda)
1170	    const torch::Tensor& proj_W,            // [d_model, d_model] float or bf16
1171	    const torch::Tensor& compress_logits,   // [csa_window] float
1172	    int N, int d_model, int csa_compress, int csa_window,
1173	    cudaStream_t stream)
1174	{
1175	    const int Nc = (N + csa_compress - 1) / csa_compress;
1176	    auto out = torch::empty({Nc, d_model},
1177	        torch::TensorOptions().dtype(torch::kFloat32).device(x_sorted_f32.device()));
1178	    const int total = Nc * d_model;
1179	    const int block = SG_TUNED_BLOCK_SIZE;
1180	    const int grid = std::min<int>(65535, (total + block - 1) / block);
1181	    if (proj_W.scalar_type() == at::ScalarType::BFloat16) {
1182	        csa_hca::csa_compress_kv_kernel<float, at::BFloat16><<<grid, block, 0, stream>>>(
1183	            x_sorted_f32.data_ptr<float>(), proj_W.data_ptr<at::BFloat16>(),
1184	            compress_logits.data_ptr<float>(), out.data_ptr<float>(),
1185	            N, d_model, Nc, csa_compress, csa_window);
1186	    } else {
1187	        csa_hca::csa_compress_kv_kernel<float, float><<<grid, block, 0, stream>>>(
1188	            x_sorted_f32.data_ptr<float>(), proj_W.data_ptr<float>(),
1189	            compress_logits.data_ptr<float>(), out.data_ptr<float>(),
1190	            N, d_model, Nc, csa_compress, csa_window);
1191	    }
1192	    SG_LAUNCH_CHECK(stream);
1193	    return out;
1194	}
1195	
1196	static torch::Tensor compress_hca(
1197	    const torch::Tensor& x_sorted_f32,
1198	    const torch::Tensor& proj_W,            // float or bf16
1199	    int N, int d_model, int hca_compress, cudaStream_t stream)
1200	{
1201	    const int Nh = (N + hca_compress - 1) / hca_compress;
1202	    auto out = torch::empty({Nh, d_model},
1203	        torch::TensorOptions().dtype(torch::kFloat32).device(x_sorted_f32.device()));
1204	    const int total = Nh * d_model;
1205	    const int block = SG_TUNED_BLOCK_SIZE;
1206	    const int grid = std::min<int>(65535, (total + block - 1) / block);
1207	    if (proj_W.scalar_type() == at::ScalarType::BFloat16) {
1208	        csa_hca::hca_compress_kv_kernel<float, at::BFloat16><<<grid, block, 0, stream>>>(
1209	            x_sorted_f32.data_ptr<float>(), proj_W.data_ptr<at::BFloat16>(),
1210	            /*hca_w=*/nullptr, out.data_ptr<float>(),
1211	            N, d_model, Nh, hca_compress);
1212	    } else {
1213	        csa_hca::hca_compress_kv_kernel<float, float><<<grid, block, 0, stream>>>(
1214	            x_sorted_f32.data_ptr<float>(), proj_W.data_ptr<float>(),
1215	            /*hca_w=*/nullptr, out.data_ptr<float>(),
1216	            N, d_model, Nh, hca_compress);
1217	    }
1218	    SG_LAUNCH_CHECK(stream);
1219	    return out;
1220	}
1221	
1222	static torch::Tensor project(
1223	    const torch::Tensor& x_f32,             // [N, d_model] float
1224	    const torch::Tensor& W,                 // [d_model, d_model] float or bf16
1225	    int N, int d_model, cudaStream_t stream)
1226	{
1227	    auto out = torch::empty({N, d_model},
1228	        torch::TensorOptions().dtype(torch::kFloat32).device(x_f32.device()));
1229	    const int total = N * d_model;
1230	    const int block = SG_TUNED_BLOCK_SIZE;
1231	    const int grid = std::min<int>(65535, (total + block - 1) / block);
1232	    if (W.scalar_type() == at::ScalarType::BFloat16) {
1233	        csa_hca::project_q_kernel<float, at::BFloat16><<<grid, block, 0, stream>>>(
1234	            x_f32.data_ptr<float>(), W.data_ptr<at::BFloat16>(), out.data_ptr<float>(),
1235	            N, d_model);
1236	    } else {
1237	        csa_hca::project_q_kernel<float, float><<<grid, block, 0, stream>>>(
1238	            x_f32.data_ptr<float>(), W.data_ptr<float>(), out.data_ptr<float>(),
1239	            N, d_model);
1240	    }
1241	    SG_LAUNCH_CHECK(stream);
1242	    return out;
1243	}
1244	
1245	// Full CSA context for the sorted sequence.
1246	static torch::Tensor csa_context(
1247	    const torch::Tensor& x_sorted,          // [N, d_model] float cuda
1248	    const torch::Tensor& q_W, const torch::Tensor& k_W, const torch::Tensor& v_W,
1249	    const torch::Tensor& compress_w,
1250	    const torch::Tensor& idx_DQ, const torch::Tensor& idx_K,
1251	    const torch::Tensor& out_W,             // float or bf16
1252	    int N, int d_model, int num_heads, int head_dim,
1253	    int csa_compress, int csa_window, int csa_topk, int indexer_rank,
1254	    cudaStream_t stream)
1255	{
1256	    auto fopt = torch::TensorOptions().dtype(torch::kFloat32).device(x_sorted.device());
1257	    const int Nc = (N + csa_compress - 1) / csa_compress;
1258	    const int topk = std::min(csa_topk, Nc);
1259	    const int block = SG_TUNED_BLOCK_SIZE;
1260	    // attn_out_proj_kernel is a float-only kernel; upcast out_W if needed.
1261	    // The Q/K/V projection kernels dispatch on dtype via the wt_t template.
1262	    const torch::Tensor out_W_f32 =
1263	        (out_W.scalar_type() == at::ScalarType::BFloat16)
1264	        ? out_W.to(torch::kFloat32) : out_W;
1265	
1266	    auto q   = project(x_sorted, q_W, N, d_model, stream);
1267	    auto c_k = compress_csa(x_sorted, k_W, compress_w, N, d_model, csa_compress, csa_window, stream);
1268	    auto c_v = compress_csa(x_sorted, v_W, compress_w, N, d_model, csa_compress, csa_window, stream);
1269	    auto win_k = project(x_sorted, k_W, N, d_model, stream);
1270	    auto win_v = project(x_sorted, v_W, N, d_model, stream);
1271	
1272	    // Indexer projections + top-k selection.
1273	    // idx_DQ and idx_K follow the same precision as the other projection weights.
1274	    const bool idx_bf16 = (idx_DQ.scalar_type() == at::ScalarType::BFloat16);
1275	    auto qI = torch::empty({N, indexer_rank}, fopt);
1276	    {
1277	        const int total = N * indexer_rank;
1278	        const int grid = std::min<int>(65535, (total + block - 1) / block);
1279	        if (idx_bf16) {
1280	            csa_hca::indexer_q_kernel<float, at::BFloat16><<<grid, block, 0, stream>>>(
1281	                x_sorted.data_ptr<float>(), idx_DQ.data_ptr<at::BFloat16>(),
1282	                qI.data_ptr<float>(), N, d_model, indexer_rank);
1283	        } else {
1284	            csa_hca::indexer_q_kernel<float, float><<<grid, block, 0, stream>>>(
1285	                x_sorted.data_ptr<float>(), idx_DQ.data_ptr<float>(),
1286	                qI.data_ptr<float>(), N, d_model, indexer_rank);
1287	        }
1288	        SG_LAUNCH_CHECK(stream);
1289	    }
1290	    auto kI = torch::empty({Nc, indexer_rank}, fopt);
1291	    {
1292	        const int total = Nc * indexer_rank;
1293	        const int grid = std::min<int>(65535, (total + block - 1) / block);
1294	        if (idx_bf16) {
1295	            csa_hca::indexer_k_kernel<float, at::BFloat16><<<grid, block, 0, stream>>>(
1296	                x_sorted.data_ptr<float>(), idx_K.data_ptr<at::BFloat16>(),
1297	                compress_w.data_ptr<float>(), kI.data_ptr<float>(),
1298	                N, d_model, Nc, indexer_rank, csa_compress, csa_window);
1299	        } else {
1300	            csa_hca::indexer_k_kernel<float, float><<<grid, block, 0, stream>>>(
1301	                x_sorted.data_ptr<float>(), idx_K.data_ptr<float>(),
1302	                compress_w.data_ptr<float>(), kI.data_ptr<float>(),
1303	                N, d_model, Nc, indexer_rank, csa_compress, csa_window);
1304	        }
1305	        SG_LAUNCH_CHECK(stream);
1306	    }
1307	    auto sel = torch::empty({N, std::max(topk, 1)},
1308	        torch::TensorOptions().dtype(torch::kInt32).device(x_sorted.device()));
1309	    {
1310	        const int grid = std::min<int>(65535, (N + block - 1) / block);
1311	        // SMEM-staged top-k scratch: block * CSA_MAX_TOPK floats (best_score) +
1312	        // block * CSA_MAX_TOPK ints (best_idx). Opt into >48KB if needed.
1313	        const size_t topk_smem_bytes =
1314	            (size_t)block * (size_t)csa_hca::CSA_MAX_TOPK
1315	            * (sizeof(float) + sizeof(int));
1316	        csa_hca::set_attn_dyn_smem(
1317	            reinterpret_cast<const void*>(
1318	                &csa_hca::csa_indexer_topk_kernel), topk_smem_bytes);
1319	        csa_hca::csa_indexer_topk_kernel<<<grid, block, topk_smem_bytes, stream>>>(
1320	            qI.data_ptr<float>(), kI.data_ptr<float>(), sel.data_ptr<int>(),
1321	            N, Nc, indexer_rank, std::max(topk, 1));
1322	        SG_LAUNCH_CHECK(stream);
1323	    }
1324	
1325	    auto concat = torch::empty({N, d_model}, fopt);
1326	    {
1327	        const int total = N * num_heads;
1328	        const int grid = std::min<int>(65535, (total + block - 1) / block);
1329	        // §4.2 dynamic shared: cp.async query staging (block * head_dim) +
1330	        // SMEM-staged online-softmax accumulator (block * head_dim). Doubled
1331	        // so the per-thread acc[] no longer occupies the register file.
1332	        const size_t qsh_bytes =
1333	            2u * sizeof(float) * (size_t)block * (size_t)head_dim;
1334	        csa_hca::set_attn_dyn_smem(
1335	            reinterpret_cast<const void*>(
1336	                &csa_hca::csa_attention_kernel), qsh_bytes);
1337	        csa_hca::csa_attention_kernel<<<grid, block, qsh_bytes, stream>>>(
1338	            q.data_ptr<float>(), c_k.data_ptr<float>(), c_v.data_ptr<float>(),
1339	            win_k.data_ptr<float>(), win_v.data_ptr<float>(),
1340	            sel.data_ptr<int>(), out_W_f32.data_ptr<float>(),
1341	            concat.data_ptr<float>(), N, Nc, d_model, num_heads, head_dim,
1342	            std::max(topk, 1), csa_window);
1343	        SG_LAUNCH_CHECK(stream);
1344	    }
1345	    auto ctx = torch::empty({N, d_model}, fopt);
1346	    {
1347	        const int total = N * d_model;
1348	        const int grid = std::min<int>(65535, (total + block - 1) / block);
1349	        csa_hca::attn_out_proj_kernel<<<grid, block, 0, stream>>>(
1350	            concat.data_ptr<float>(), out_W_f32.data_ptr<float>(),
1351	            ctx.data_ptr<float>(), N, d_model);
1352	        SG_LAUNCH_CHECK(stream);
1353	    }
1354	    return ctx;
1355	}
1356	
1357	static torch::Tensor hca_context(
1358	    const torch::Tensor& x_sorted,
1359	    const torch::Tensor& q_W, const torch::Tensor& k_W, const torch::Tensor& v_W,
1360	    const torch::Tensor& out_W,             // float or bf16
1361	    int N, int d_model, int num_heads, int head_dim,
1362	    int hca_compress, int csa_window, cudaStream_t stream)
1363	{
1364	    auto fopt = torch::TensorOptions().dtype(torch::kFloat32).device(x_sorted.device());
1365	    const int Nh = (N + hca_compress - 1) / hca_compress;
1366	    const int block = SG_TUNED_BLOCK_SIZE;
1367	    // attn_out_proj_kernel is float-only; upcast out_W if needed.
1368	    const torch::Tensor out_W_f32 =
1369	        (out_W.scalar_type() == at::ScalarType::BFloat16)
1370	        ? out_W.to(torch::kFloat32) : out_W;
1371	
1372	    auto q   = project(x_sorted, q_W, N, d_model, stream);
1373	    auto c_k = compress_hca(x_sorted, k_W, N, d_model, hca_compress, stream);
1374	    auto c_v = compress_hca(x_sorted, v_W, N, d_model, hca_compress, stream);
1375	    auto win_k = project(x_sorted, k_W, N, d_model, stream);
1376	    auto win_v = project(x_sorted, v_W, N, d_model, stream);
1377	
1378	    auto concat = torch::empty({N, d_model}, fopt);
1379	    {
1380	        const int total = N * num_heads;
1381	        const int grid = std::min<int>(65535, (total + block - 1) / block);
1382	        // §4.2 dynamic shared: cp.async query staging (block * head_dim) +
1383	        // SMEM-staged online-softmax accumulator (block * head_dim).
1384	        const size_t qsh_bytes =
1385	            2u * sizeof(float) * (size_t)block * (size_t)head_dim;
1386	        csa_hca::set_attn_dyn_smem(
1387	            reinterpret_cast<const void*>(
1388	                &csa_hca::hca_attention_kernel), qsh_bytes);
1389	        csa_hca::hca_attention_kernel<<<grid, block, qsh_bytes, stream>>>(
1390	            q.data_ptr<float>(), c_k.data_ptr<float>(), c_v.data_ptr<float>(),
1391	            win_k.data_ptr<float>(), win_v.data_ptr<float>(),
1392	            concat.data_ptr<float>(), N, Nh, d_model, num_heads, head_dim,
1393	            csa_window);
1394	        SG_LAUNCH_CHECK(stream);
1395	    }
1396	    auto ctx = torch::empty({N, d_model}, fopt);
1397	    {
1398	        const int total = N * d_model;
1399	        const int grid = std::min<int>(65535, (total + block - 1) / block);
1400	        csa_hca::attn_out_proj_kernel<<<grid, block, 0, stream>>>(
1401	            concat.data_ptr<float>(), out_W_f32.data_ptr<float>(),
1402	            ctx.data_ptr<float>(), N, d_model);
1403	        SG_LAUNCH_CHECK(stream);
1404	    }
1405	    return ctx;
1406	}
1407	
1408	// PEER routing + per-element expert MLP. Reuses the existing expert tensors.
1409	//
1410	// MULTI-HEAD product-key top-k routing (restored): the PEER weights are stacked
1411	// per head — peer_query_Ws = [num_peer_heads, d_model, peer_in];
1412	// prod_keys_{A,B} = [num_peer_heads, pk_dim, d_model/2]. We LOOP over the heads
1413	// (NOT collapse the head axis): per head, query = peer_input @ Wq.t() [N,d_model];
1414	// query is split into halves q_a / q_b (half = d_model/2); we score against
1415	// product-key sub-codebooks A and B, take the top-k of EACH (k = peer_topk,
1416	// default 4), form the k×k Cartesian product of candidate experts
1417	// (expert = a_idx * na + b_idx, na == pk_dim), softmax-weight them by the
1418	// per-axis scores (temperature 10), run the per-element expert MLP for each of
1419	// the k² selected experts and accumulate the routing-weighted combination; the
1420	// head outputs are then AVERAGED (÷ num_peer_heads). This matches the eager net
1421	// (grokking_optimizers/optimizers/supergrok2.py: SuperGrok2 forward, ~L705-750),
1422	// the bilevel adjoint (csrc/algorithms/supergrok2_bilevel_adjoint.h:
1423	// peer_head_backward + its driver loop) and the Pallas backend
1424	// (csrc/backends/pallas/launch_supergrok2.py: peer_expert_forward) — all three
1425	// use the identical per-head layout. The previous code FLATTENED the head axis
1426	// (`peer_query_Ws.reshape({-1, d_model})`, `prod_keys_A.reshape({-1, half})`),
1427	// which corrupted the routing and crashed on the reshape (shape '[-1, 44]' for
1428	// size 192). When product keys are absent we fall back to a single shared
1429	// expert (index 0), unchanged.
1430	static torch::Tensor peer_expert_forward(
1431	    const torch::Tensor& peer_input,        // [N, peer_in] float (gru ⊕ csa ⊕ hca ⊕ g ⊕ s)
1432	    const torch::Tensor& g_elem,            // [N] float — per-element grad (expert-MLP input)
1433	    const torch::Tensor& peer_query_Ws,     // [num_peer_heads, d_model, peer_in]
1434	    const torch::Tensor& prod_keys_A,
1435	    const torch::Tensor& prod_keys_B,
1436	    const torch::Tensor& expert_W1,         // [num_experts, expert_hidden] (per-elem MLP)
1437	    const torch::Tensor& expert_b1,
1438	    const torch::Tensor& expert_W2,
1439	    const torch::Tensor& expert_b2,
1440	    int N, int d_model, int num_experts, int expert_hidden,
1441	    torch::Tensor& expert_counts,
1442	    int peer_topk = 4)
1443	{
1444	    auto lopt = torch::TensorOptions().dtype(torch::kLong).device(peer_input.device());
1445	    auto fopt32 = torch::TensorOptions().dtype(torch::kFloat32).device(peer_input.device());
1446	
1447	    // Per-element expert MLP weights (shared codebook, indexed per element).
1448	    // The MLP input is the per-element grad g (matches eager `g_exp` at L742 and
1449	    // adjoint `g` at peer_head_backward), NOT a mean over feature columns.
1450	    auto scalar_in = g_elem.reshape({N}).to(torch::kFloat32);               // [N]
1451	    auto W1 = expert_W1.reshape({num_experts, -1}).to(torch::kFloat32);     // [E, H]
1452	    auto b1 = expert_b1.reshape({num_experts, -1}).to(torch::kFloat32);     // [E, H]
1453	    auto W2 = expert_W2.reshape({num_experts, -1}).to(torch::kFloat32);     // [E, H]
1454	    auto b2 = expert_b2.reshape({num_experts, -1}).to(torch::kFloat32);     // [E, 1]
1455	    const int H = W1.size(1);
1456	
1457	    // Apply the per-element MLP for a [N, A] block of expert indices, weighted
1458	    // by routing_w [N, A], reduced over A. scalar_in [N] is the (broadcast) MLP
1459	    // input. Returns [N].
1460	    auto run_experts = [&](const torch::Tensor& expert_idx,       // [N, A] long
1461	                           const torch::Tensor& routing_w) {      // [N, A] float
1462	        const int64_t A = expert_idx.size(1);
1463	        auto flat = expert_idx.reshape({-1});                     // [N*A]
1464	        auto g_W1 = W1.index_select(0, flat).reshape({N, A, H});  // [N,A,H]
1465	        auto g_b1 = b1.index_select(0, flat).reshape({N, A, H});
1466	        auto g_W2 = W2.index_select(0, flat).reshape({N, A, H});
1467	        auto g_b2 = b2.index_select(0, flat).reshape({N, A});     // [N,A]
1468	        auto si   = scalar_in.reshape({N, 1, 1});                 // [N,1,1]
1469	        auto hidden = (g_W1 * si + g_b1).clamp_min(0.0f);         // [N,A,H] ReLU
1470	        auto out    = (g_W2 * hidden).sum(2) + g_b2;              // [N,A]
1471	        return (out * routing_w).sum(1);                          // [N]
1472	    };
1473	
1474	    // Per-head PEER product-key routing (matches eager SuperGrok2.forward +
1475	    // bilevel adjoint peer_head_backward + Pallas peer_expert_forward).
1476	    // peer_query_Ws = [num_peer_heads, d_model, peer_in]; prod_keys_{A,B} =
1477	    // [num_peer_heads, pk_dim, d_model/2]. half = d_model/2 (NOT Q/2 — query is
1478	    // exactly d_model wide). Each head routes independently; head outputs are
1479	    // averaged (÷ num_peer_heads).
1480	    torch::Tensor out = torch::zeros({N}, fopt32);   // [N]
1481	    std::vector<torch::Tensor> count_chunks;         // each [N*A] long, for counts
1482	    if (prod_keys_A.defined() && prod_keys_A.numel() > 0 &&
1483	        peer_query_Ws.defined() && peer_query_Ws.dim() == 3) {
1484	        const int num_peer_heads = static_cast<int>(peer_query_Ws.size(0));
1485	        const int half = d_model / 2;
1486	        const double T = 10.0;   // gate temperature (matches adjoint PEER head)
1487	        const bool has_B = prod_keys_B.defined() && prod_keys_B.numel() > 0;
1488	        for (int h = 0; h < num_peer_heads; ++h) {
1489	            auto Wq = peer_query_Ws.select(0, h).to(torch::kFloat32);   // [d_model, peer_in]
1490	            auto query = peer_input.matmul(Wq.transpose(0, 1));         // [N, d_model]
1491	            auto A = prod_keys_A.select(0, h).to(torch::kFloat32);      // [pk_dim, half]
1492	            const int na = static_cast<int>(A.size(0));                 // == pk_dim
1493	            auto qa = query.narrow(1, 0, half);                         // [N, half]
1494	            auto sa = qa.matmul(A.transpose(0, 1));                     // [N, pk_dim]
1495	            const int ka = std::min<int>(std::max(peer_topk, 1), na);
1496	            auto ta = sa.topk(ka, -1);
1497	            auto top_a_vals = std::get<0>(ta), top_a_idx = std::get<1>(ta);
1498	            auto soft_a = torch::softmax(top_a_vals * T, -1);           // [N, ka]
1499	            torch::Tensor expert_idx, routing_w;
1500	            if (has_B && (d_model - half) > 0) {
1501	                auto B = prod_keys_B.select(0, h).to(torch::kFloat32);  // [pk_dim, half]
1502	                auto qb = query.narrow(1, half, d_model - half);        // [N, d_model-half]
1503	                auto sb = qb.matmul(B.transpose(0, 1));                 // [N, pk_dim]
1504	                const int nb = static_cast<int>(B.size(0));
1505	                const int kb = std::min<int>(std::max(peer_topk, 1), nb);
1506	                auto tb = sb.topk(kb, -1);
1507	                auto top_b_vals = std::get<0>(tb), top_b_idx = std::get<1>(tb);
1508	                auto soft_b = torch::softmax(top_b_vals * T, -1);       // [N, kb]
1509	                // k_a × k_b Cartesian product of candidate experts + weights.
1510	                // expert = a_idx * na + b_idx (na == pk_dim — matches eager L724
1511	                // `* self.pk_dim` and adjoint L639 `* pk_dim`).
1512	                expert_idx = (top_a_idx.unsqueeze(2) * na + top_b_idx.unsqueeze(1))
1513	                                 .reshape({N, ka * kb}).clamp(0, num_experts - 1);
1514	                routing_w = (soft_a.unsqueeze(2) * soft_b.unsqueeze(1)).reshape({N, ka * kb});
1515	            } else {
1516	                // Single sub-codebook: top-k over A directly.
1517	                expert_idx = top_a_idx.clamp(0, num_experts - 1);       // [N, ka]
1518	                routing_w  = soft_a;                                    // [N, ka]
1519	            }
1520	            out = out + run_experts(expert_idx, routing_w);             // [N]
1521	            count_chunks.push_back(expert_idx.reshape({-1}));
1522	        }
1523	        out = out / static_cast<float>(std::max(num_peer_heads, 1));
1524	    } else {
1525	        // No product keys → single shared expert (index 0), weight 1.
1526	        auto expert_idx = torch::zeros({N, 1}, lopt);
1527	        auto routing_w  = torch::ones({N, 1}, fopt32);
1528	        out = run_experts(expert_idx, routing_w);
1529	        count_chunks.push_back(expert_idx.reshape({-1}));
1530	    }
1531	    auto count_idx = count_chunks.size() == 1 ? count_chunks[0]
1532	                                              : torch::cat(count_chunks, 0);
1533	
1534	    // Update expert activation counts (best-effort; reused by recycling). Now
1535	    // counts every selected expert in the top-k combination, not just one.
1536	    if (expert_counts.defined() && expert_counts.numel() >= num_experts) {
1537	        auto counts = torch::zeros({num_experts}, lopt);
1538	        counts.scatter_add_(0, count_idx, torch::ones_like(count_idx));
1539	        expert_counts.add_(counts.to(expert_counts.dtype()));
1540	    }
1541	    (void)H; (void)expert_hidden;
1542	    return out;  // [N] float
1543	}
