1547	// Internal: full meta-model forward + Adam apply for ONE parameter tensor.
1548	static void csa_hca_step_one(
1549	    torch::Tensor& param, torch::Tensor& grad, torch::Tensor& sharpness,
1550	    torch::Tensor& exp_avg, torch::Tensor& exp_avg_sq, torch::Tensor& mu,
1551	    torch::Tensor& slow,
1552	    torch::Tensor& gru_state,
1553	    torch::Tensor& input_proj_W, torch::Tensor& input_proj_b,
1554	    torch::Tensor& csa_q_W, torch::Tensor& csa_k_W, torch::Tensor& csa_v_W,
1555	    torch::Tensor& csa_compress_w,
1556	    torch::Tensor& csa_idx_DQ, torch::Tensor& /*csa_idx_UQ*/, torch::Tensor& csa_idx_K,
1557	    torch::Tensor& csa_out_W,
1558	    torch::Tensor& hca_q_W, torch::Tensor& hca_k_W, torch::Tensor& hca_v_W,
1559	    torch::Tensor& hca_out_W,
1560	    torch::Tensor& gru_Wz, torch::Tensor& gru_bz,
1561	    torch::Tensor& gru_Wr, torch::Tensor& gru_br,
1562	    torch::Tensor& gru_Wh, torch::Tensor& gru_bh,
1563	    torch::Tensor& peer_query_Ws, torch::Tensor& prod_keys_A, torch::Tensor& prod_keys_B,
1564	    torch::Tensor& expert_W1, torch::Tensor& expert_b1,
1565	    torch::Tensor& expert_W2, torch::Tensor& expert_b2,
1566	    float rescale, float alpha_mu, float gru_decay, float lamb_eff,
1567	    float beta1, float beta2, float lr, float wd_eff, float eps,
1568	    float bc1, float bc2,
1569	    int d_model, int num_heads,
1570	    int expert_hidden, int num_experts,
1571	    int csa_compress, int csa_window, int csa_topk,
1572	    int hca_compress, int indexer_rank,
1573	    torch::Tensor& expert_counts,
1574	    int peer_topk,
1575	    cudaStream_t stream)
1576	{
1577	    // SG2 runs sequence-attention over the N "tokens" (materializes [N,d_model]
1578	    // + N*N attention), so it OOMs far below INT_MAX elements — the int domain
1579	    // here is safe in practice. Guard the truncation loudly anyway so a >2^31
1580	    // element param ERRORS instead of silently wrapping `N` into corruption.
1581	    TORCH_CHECK(grad.numel() <= static_cast<int64_t>(INT_MAX),
1582	                "supergrok2: param numel ", grad.numel(),
1583	                " exceeds INT_MAX; the SG2 attention path uses 32-bit token "
1584	                "indexing (it materializes an N*N attention map and cannot "
1585	                "reach this size in practice).");
1586	    const int N = static_cast<int>(grad.numel());
1587	    if (N == 0) return;
1588	    const int head_dim = d_model / std::max(num_heads, 1);
1589	    auto dev = grad.device();
1590	    auto fopt = torch::TensorOptions().dtype(torch::kFloat32).device(dev);
1591	
1592	    // (1) input projection + sort key.
1593	    // input_proj_W/b pass through at their native dtype (float or bf16).
1594	    auto x_out = torch::empty({N, d_model}, fopt);
1595	    auto sort_keys = torch::empty({N}, fopt);
1596	    auto sort_idx  = torch::empty({N}, torch::TensorOptions().dtype(torch::kInt32).device(dev));
1597	    // sg2_input_proj_sort_kernel reads input_proj_W and input_proj_b through the
1598	    // SAME wt_t template, so they must share a dtype. The Python weight bundle
1599	    // converts the weight matrix to bf16 (projection_precision='bf16') but leaves
1600	    // the bias fp32, so the bf16 branch would call data_ptr<at::BFloat16>() on an
1601	    // fp32 bias ("expected BFloat16 but found Float"). Coerce the bias to the
1602	    // weight's dtype. Held at function scope so it outlives the async launch.
1603	    const torch::Tensor input_proj_b_m =
1604	        (input_proj_b.scalar_type() == input_proj_W.scalar_type())
1605	        ? input_proj_b : input_proj_b.to(input_proj_W.scalar_type());
1606	    {
1607	        const int block = SG_TUNED_BLOCK_SIZE;
1608	        const int grid = std::min<int>(65535, (N + block - 1) / block);
1609	        const bool wt_bf16 = (input_proj_W.scalar_type() == at::ScalarType::BFloat16);
1610	        AT_DISPATCH_FLOATING_TYPES_AND2(
1611	            at::ScalarType::Half, at::ScalarType::BFloat16,
1612	            grad.scalar_type(), "csa_hca_input_proj_sort", [&] {
1613	                if (wt_bf16) {
1614	                    sg2_input_proj_sort_kernel<scalar_t, at::BFloat16><<<grid, block, 0, stream>>>(
1615	                        grad.data_ptr<scalar_t>(), sharpness.data_ptr<scalar_t>(),
1616	                        x_out.data_ptr<float>(), sort_keys.data_ptr<float>(),
1617	                        sort_idx.data_ptr<int>(),
1618	                        input_proj_W.data_ptr<at::BFloat16>(),
1619	                        input_proj_b_m.data_ptr<at::BFloat16>(),
1620	                        N, d_model);
1621	                } else {
1622	                    sg2_input_proj_sort_kernel<scalar_t, float><<<grid, block, 0, stream>>>(
1623	                        grad.data_ptr<scalar_t>(), sharpness.data_ptr<scalar_t>(),
1624	                        x_out.data_ptr<float>(), sort_keys.data_ptr<float>(),
1625	                        sort_idx.data_ptr<int>(),
1626	                        input_proj_W.data_ptr<float>(), input_proj_b_m.data_ptr<float>(),
1627	                        N, d_model);
1628	                }
1629	                SG_LAUNCH_CHECK(stream);
1630	            });
1631	    }
1632	    // Sort the sequence by |grad| ASCENDING so attention sees the SAME ordering
1633	    // the eager net (supergrok2.py:676 `g.abs().argsort()`) and the bilevel
1634	    // adjoint oracle (supergrok2_bilevel_adjoint.h:543 "ascending (oracle)")
1635	    // were trained on. CSA/HCA are sequence attention with windows/compression/
1636	    // top-k — order-DEPENDENT, NOT permutation-equivariant — so a descending sort
1637	    // feeds the attention a distribution it never saw and produces garbage
1638	    // contexts → garbage routing. (The PEER tail downstream IS per-element/
1639	    // permutation-equivariant, so unsorting the [N] expert output once via this
1640	    // same `perm` is correct regardless of sort direction.) Remember the
1641	    // permutation to unsort the result.
1642	    auto sorted = sort_keys.sort(/*dim=*/0, /*descending=*/false);
1643	    auto perm = std::get<1>(sorted).to(torch::kLong);          // [N]
1644	    auto x_sorted = x_out.index_select(0, perm).contiguous();  // [N, d_model]
1645	
1646	    // (2) CSA + HCA contexts.
1647	    // Projection weights pass through at their native dtype (float or bf16);
1648	    // the detail:: helpers dispatch on scalar_type() internally.
1649	    // csa_compress_w stays float (it is a learned logit, not a GEMM operand).
1650	    auto csa_ctx = detail::csa_context(
1651	        x_sorted, csa_q_W, csa_k_W, csa_v_W,
1652	        csa_compress_w.to(torch::kFloat32),
1653	        csa_idx_DQ, csa_idx_K, csa_out_W,
1654	        N, d_model, num_heads, head_dim,
1655	        csa_compress, csa_window, csa_topk, indexer_rank, stream);
1656	    auto hca_ctx = detail::hca_context(
1657	        x_sorted, hca_q_W, hca_k_W, hca_v_W, hca_out_W,
1658	        N, d_model, num_heads, head_dim, hca_compress, csa_window, stream);
1659	
1660	    // (3) Build the real-width PEER input, then PEER routing + expert MLP.
1661	    //
1662	    // The eager net (supergrok2.py SuperGrok2.forward, ~L697) builds
1663	    //   peer_input = cat(new_gru[N,gru_hidden], csa_ctx[N,d_model],
1664	    //                    hca_ctx[N,d_model], g[N,1], s[N,1])  = [N, peer_in].
1665	    // peer_expert_forward is purely per-element (no reduction over N), so its
1666	    // output is permutation-equivariant in the row axis: computing peer_input in
1667	    // |grad|-SORTED order here and unsorting the result ONCE at step (4) via the
1668	    // SAME `perm` is identical to the eager net's original-order computation.
1669	    // csa_ctx/hca_ctx are already in sorted order (they come straight off
1670	    // x_sorted with no unsort), so we sort g/s by the SAME `perm` (from L~1600)
1671	    // to keep every column of peer_input describing the same element per row.
1672	    auto fopt32 = torch::TensorOptions().dtype(torch::kFloat32).device(dev);
1673	    auto g_sorted = grad.reshape({-1}).to(torch::kFloat32).index_select(0, perm);       // [N]
1674	    auto s_sorted = sharpness.reshape({-1}).to(torch::kFloat32).index_select(0, perm);  // [N]
1675	    // peer_in is read from the real weight (peer_query_Ws = [num_peer_heads,
1676	    // d_model, peer_in]); derive gru_hidden = peer_in - 2*d_model - 2.
1677	    const int peer_input_dim = (peer_query_Ws.defined() && peer_query_Ws.dim() == 3)
1678	                                   ? static_cast<int>(peer_query_Ws.size(2))
1679	                                   : (2 * d_model + 2);
1680	    const int gru_hidden = peer_input_dim - 2 * d_model - 2;
1681	    // Matrix-GRU forward (MiniGRU), reconstructed to match the eager net
1682	    // (supergrok2.py CSAHCAMetaNet.forward:691-700) and the bilevel adjoint
1683	    // oracle (supergrok2_bilevel_adjoint.h:568-585). gru_new feeds the PEER
1684	    // routing input (20 of 22 peer_input columns are csa/hca/gru), so a zero
1685	    // placeholder makes expert selection diverge from the eager net → thrash.
1686	    //
1687	    // ALL terms fed to the GRU share the SAME |grad|-ASCENDING sorted order as
1688	    // csa_ctx/hca_ctx/g_sorted/s_sorted, so the per-element GRU output is in
1689	    // sorted order; it is written into peer_input directly (no unsort here —
1690	    // the [N] expert output is unsorted once at step (4)).
1691	    //
1692	    //   gru_input = cat(g, s, csa_ctx, hca_ctx)              [N, 2+2*d]
1693	    //   xh        = cat(gru_input, h_old)                    [N, gru_in+gh]
1694	    //   z = sigmoid(xh @ Wz.t() + bz) ; r = sigmoid(xh @ Wr.t() + br)
1695	    //   xrh       = cat(gru_input, r*h_old)
1696	    //   h_tilde   = tanh(xrh @ Wh.t() + bh)
1697	    //   h_new     = (1-z)*h_old + z*h_tilde                  [N, gru_hidden]
1698	    // Weights are PyTorch nn.Linear .weight [out=gh, in], so x @ W.t() is the
1699	    // forward (matches linear_fwd in the adjoint header). gru_state is the
1700	    // PER-ELEMENT carried state [N, gru_hidden] (supergrok2.py:1391/1404), NOT a
1701	    // [gru_hidden] broadcast — sort it by the same `perm`.
1702	    torch::Tensor gru_new;
1703	    // gru_hidden <= 0 is the only legitimate no-GRU case (peer_input has no GRU
1704	    // block). When gru_hidden > 0 and the GRU weights are present, the carried
1705	    // state MUST be [N, gru_hidden] — error LOUDLY on a mismatch rather than
1706	    // silently falling back to zeros, which would reintroduce the exact
1707	    // zero-GRU routing-garbage bug this reconstruction fixes.
1708	    const bool have_gru = gru_hidden > 0 && gru_Wz.defined() && gru_Wz.numel() > 0;
1709	    if (have_gru) {
1710	        TORCH_CHECK(gru_state.defined()
1711	                    && gru_state.numel() == static_cast<int64_t>(N) * gru_hidden,
1712	                    "supergrok2: gru_state numel ",
1713	                    (gru_state.defined() ? gru_state.numel() : -1),
1714	                    " != N*gru_hidden (", static_cast<int64_t>(N) * gru_hidden,
1715	                    ") — the matrix-GRU forward needs the per-element carried "
1716	                    "state [N, gru_hidden]; a mismatch would silently corrupt "
1717	                    "PEER routing.");
1718	        auto h_old = gru_state.reshape({N, gru_hidden}).to(torch::kFloat32)
1719	                         .index_select(0, perm).contiguous();          // [N, gh] sorted
1720	        auto gru_input = torch::cat({g_sorted.unsqueeze(1), s_sorted.unsqueeze(1),
1721	                                     csa_ctx, hca_ctx}, 1);             // [N, 2+2*d]
1722	        auto Wz = gru_Wz.to(torch::kFloat32), Wr = gru_Wr.to(torch::kFloat32),
1723	             Wh = gru_Wh.to(torch::kFloat32);
1724	        auto bz = gru_bz.to(torch::kFloat32), br = gru_br.to(torch::kFloat32),
1725	             bh = gru_bh.to(torch::kFloat32);
1726	        auto xh = torch::cat({gru_input, h_old}, 1);
1727	        auto z = torch::sigmoid(torch::mm(xh, Wz.t()) + bz.unsqueeze(0));
1728	        auto r = torch::sigmoid(torch::mm(xh, Wr.t()) + br.unsqueeze(0));
1729	        auto xrh = torch::cat({gru_input, r * h_old}, 1);
1730	        auto h_tilde = torch::tanh(torch::mm(xrh, Wh.t()) + bh.unsqueeze(0));
1731	        gru_new = (1.0f - z) * h_old + z * h_tilde;                     // [N, gh] sorted
1732	        // Persist the updated state back IN-PLACE (the fused Python path
1733	        // supergrok2.py:1646-1694 passes gru_state by reference and never
1734	        // reassigns it, unlike the eager paths). Write back in ORIGINAL element
1735	        // order (eager's new_gru / the persistent buffer are original order):
1736	        // unsort via the same perm, then copy_ into gru_state (downcasts to the
1737	        // buffer's dtype, e.g. bf16).
1738	        auto gru_new_orig = torch::empty({N, gru_hidden}, fopt32);
1739	        gru_new_orig.index_copy_(0, perm, gru_new);
1740	        gru_state.copy_(gru_new_orig.reshape(gru_state.sizes()));
1741	    } else {
1742	        // gru_hidden == 0 or weights/state absent: peer_input has no GRU block.
1743	        gru_new = torch::zeros({N, std::max(gru_hidden, 0)}, fopt32);
1744	    }
1745	    auto peer_input = torch::cat({gru_new, csa_ctx, hca_ctx,
1746	                                  g_sorted.unsqueeze(1), s_sorted.unsqueeze(1)}, 1);  // [N, peer_in]
1747	    auto expert_sorted = detail::peer_expert_forward(
1748	        peer_input, g_sorted, peer_query_Ws, prod_keys_A, prod_keys_B,
1749	        expert_W1, expert_b1, expert_W2, expert_b2,
1750	        N, d_model, num_experts, expert_hidden, expert_counts,
1751	        /*peer_topk=*/peer_topk);  // [N] sorted — real per-head product-key top-k
1752	                                   // combination (configurable; default 4 = PEER top-4)
1753	
1754	    // (4) Unsort expert output back to original element order, scale.
1755	    auto expert_out = torch::empty({N}, fopt);
1756	    expert_out.index_copy_(0, perm, expert_sorted);
1757	    expert_out.mul_(rescale);
1758	
1759	    // (5) Adam apply. NOTE: the matrix-GRU above feeds ONLY the PEER routing
1760	    // input (peer_input), exactly as the eager net — its output does NOT enter
1761	    // the parameter update directly. sg2_apply_step's separate `mu_state`/
1762	    // `gru_decay` blend is an expert-output EMA (a temporal smoothing of
1763	    // expert_out), distinct from the matrix GRU, so there is no double-count.
1764	    // The restored grokfast term lives in sg2_apply_step too: a separate `slow`
1765	    // EMA of g (decay alpha_mu) amplified by `lamb_eff` (= lamb·ramp·gate, was
1766	    // (void)-ed before) — see csrc/algorithms/supergrok2.h.
1767	    {
1768	        const int block = SG_TUNED_BLOCK_SIZE;
1769	        const int grid = std::min<int>(65535, (N + block - 1) / block);
1770	        AT_DISPATCH_FLOATING_TYPES_AND2(
1771	            at::ScalarType::Half, at::ScalarType::BFloat16,
1772	            param.scalar_type(), "csa_hca_apply", [&] {
1773	                sg2_apply_kernel<scalar_t, scalar_t><<<grid, block, 0, stream>>>(
1774	                    param.data_ptr<scalar_t>(),
1775	                    exp_avg.data_ptr<float>(), exp_avg_sq.data_ptr<float>(),
1776	                    mu.data_ptr<float>(), slow.data_ptr<float>(),
1777	                    grad.data_ptr<scalar_t>(),
1778	                    expert_out.data_ptr<float>(),
1779	                    alpha_mu, gru_decay, lamb_eff, lr, beta1, beta2, eps, wd_eff,
1780	                    bc1, bc2, N);
1781	                SG_LAUNCH_CHECK(stream);
1782	            });
1783	    }
1784	}
