74	// The L3-REAL decoder megakernel needs the token path + a grad-partial workspace
75	// in addition to the FuseTier::{L1,L3} ABI. We keep it a SEPARATE kernel +
76	// launcher (not folded into fused_megakernel) so the surrogate path is untouched.
77	//
78	// Workspace layout (one flat float buffer the host allocates + the kernel owns):
79	//   [0 .. nCTA*total)              : per-CTA grad partials (cta-major)
80	//   [nCTA*total .. nCTA*total+nCTA): per-CTA loss partials (NLL sum per slice)
81	//   [.. +1)                        : the reduced scalar loss (loss/B) the host reads
82	// total == kDecTotalElems == 422755.
83	
84	struct DecoderTokenCtx {
85	    const int* tokens;   // [B, kSeq] int32 token ids in [0, kVocab)
86	    const int* targets;  // [B]       int32 target ids
87	    int        B;        // batch size (full-batch in the race ≈ 4191)
88	    float*     workspace; // grad partials + loss partials + reduced loss
89	    float*     loss_out;  // device float the kernel writes the mean loss into
90	};
91	
92	// ── The persistent megakernel (L3-REAL). gridDim.x = #SMs (one CTA/SM), 256
93	//    threads/CTA. The smem holds ONE DecSampleSmem (≈42 KB, < 48 KB static cap —
94	//    no dynamic-smem opt-in, so the occupancy≥1 guard with dynamicSMemBytes=0 in
95	//    the launcher is unchanged). ────────────────────────────────────────────────
96	// sizes/offsets are NOT host-passed: the per-tensor numel/offset live in the
97	// generated __constant__ tables kDecSizes/kDecOffsets (decoder_layout.cuh), so
98	// the reduce + optimizer phases read them directly. This also lets the host side
99	// (dispatch.cpp) avoid building any layout tensors.
100	template <OptId Opt>
101	__global__ void __launch_bounds__(256)
102	fused_decoder_megakernel(PersistentContext ctx,
103	                         float* __restrict__ params,
104	                         DecoderTokenCtx tok,
105	                         float* __restrict__ grad,        // reduced grad [total]
106	                         float lr, int step, FusedOptState st) {
107	    __shared__ DecSampleSmem sm;
108	    GridBarrier bar = ctx.barrier();
109	    const int cta = blockIdx.x;
110	    const int nCTA = (int)ctx.n_ctas;
111	    const int64_t total = kDecTotalElems;
112	    float* my_partial = tok.workspace + (int64_t)cta * total;   // this CTA's dW
113	    float* loss_part = tok.workspace + (int64_t)nCTA * total;   // [nCTA]
114	
115	    // §3.4 register repartition (producer WG gives back, consumer WG claims).
116	    const int wg = threadIdx.x / 128;
117	    // warp-specialize prims live in sg::sm90::wgs (this file is sg::fused::sm90)
118	    if (wg == 0) ::sg::sm90::wgs::warpgroup_reg_dealloc<32>();
119	    else         ::sg::sm90::wgs::warpgroup_reg_alloc<200>();
120	
121	    // ── P0: zero this CTA's grad-partial slice + its loss slot. ───────────────
122	    for (int64_t i = threadIdx.x; i < total; i += blockDim.x) my_partial[i] = 0.0f;
123	    if (threadIdx.x == 0) loss_part[cta] = 0.0f;
124	    bar.sync();   // B0
125	
126	    // ── P1: batch-parallel fwd+bwd. Fixed contiguous slice [b0,b1) for this CTA.
127	    DecWeights w = dec_bind(params);
128	    DecGrad g = dec_bind_grad(my_partial);
129	    // Even split with remainder to the low CTAs (contiguous, deterministic).
130	    const int B = tok.B;
131	    const int base = B / nCTA, rem = B % nCTA;
132	    const int b0 = cta * base + (cta < rem ? cta : rem);
133	    const int cnt = base + (cta < rem ? 1 : 0);
134	    const int b1 = b0 + cnt;
135	    __shared__ int tok_s[dec::kSeq];   // this sample's token ids (broadcast)
136	    __shared__ int tgt_s;
137	    float nll_acc = 0.0f;              // fp32 slice accumulator (thread-0 holds it)
138	    for (int b = b0; b < b1; ++b) {
139	        if (threadIdx.x < dec::kSeq) tok_s[threadIdx.x] = tok.tokens[(int64_t)b * dec::kSeq + threadIdx.x];
140	        if (threadIdx.x == 0) tgt_s = tok.targets[b];
141	        __syncthreads();
142	        float nll = dec_forward_sample(w, tok_s, tgt_s, &sm);
143	        dec_backward_sample(w, g, tok_s, tgt_s, B, &sm);
144	        if (threadIdx.x == 0) nll_acc += nll;   // fixed-order fp32 sum within slice
145	        __syncthreads();   // sample boundary: all grad writes done before reuse
146	    }
147	    if (threadIdx.x == 0) loss_part[cta] = nll_acc;
148	    bar.sync();   // B1: all CTA partials + loss slots complete
149	
150	    // ── P2: deterministic cross-CTA reduce. Work-steal the param ELEMENT-RANGES
151	    //    (one task = one parameter tensor; sum its elements across CTAs in
152	    //    ascending CTA index). The summation ORDER (ascending cta) is fixed, so
153	    //    the result is deterministic regardless of which CTA grabs the task. ────
154	    {
155	        __shared__ int task_slot;
156	        TaskQueue q = ctx.queue();
157	        for (int t = q.next_block(&task_slot); t < kDecNumTensors;
158	             t = q.next_block(&task_slot)) {
159	            const int n = kDecSizes[t];
160	            const int64_t off = (int64_t)kDecOffsets[t];
161	            for (int i = threadIdx.x; i < n; i += blockDim.x) {
162	                float acc = 0.0f;
163	                // ascending CTA index → fixed fp32 summation order (deterministic).
164	                for (int c = 0; c < nCTA; ++c)
165	                    acc += tok.workspace[(int64_t)c * total + off + i];
166	                grad[off + i] = acc;
167	            }
168	        }
169	    }
170	    // Loss reduction (fp64 ordered) by CTA 0 only — the 1e-5 loss rel-tol is the
171	    // tightest gate; fp32 atomic-summing ~4191 terms can miss it.
172	    if (cta == 0 && threadIdx.x == 0) {
173	        double s = 0.0;
174	        for (int c = 0; c < nCTA; ++c) s += (double)loss_part[c];
175	        float mean = (float)(s / (double)B);
176	        *tok.loss_out = mean;
177	    }
178	    bar.sync_reset(ctx.g_next_task);   // B2: reduced grad ready; reset queue for P3
179	
180	    // ── P3: the REAL optimizer tail over the reduced grad (work-steal the 30
181	    //    tensors). apply_optimizer<Opt> is the canonical csrc/algorithms math. ──
182	    st.lr = lr;
183	    {
184	        __shared__ int task_slot;
185	        TaskQueue q = ctx.queue();
186	        for (int t = q.next_block(&task_slot); t < kDecNumTensors;
187	             t = q.next_block(&task_slot)) {
188	            const int n = kDecSizes[t];
189	            const int64_t off = (int64_t)kDecOffsets[t];
190	            const FusedOptState ts = rebase_state<Opt>(st, off);
191	            float* __restrict__ p = params + off;
192	            const float* __restrict__ gg = grad + off;
193	            for (int i = threadIdx.x; i < n; i += blockDim.x)
194	                apply_optimizer<Opt>(p, gg, (int64_t)i, step, ts);
195	        }
196	    }
197	}
