199	// ── Host launcher — one persistent CTA per SM, 256 threads/CTA (2 warp-groups).
200	//    Mirrors launch_fused_megakernel's hang-freedom contract: occupancy≥1 or
201	//    refuse (the GridBarrier rendezvous of n_ctas CTAs can never complete if a
202	//    CTA can't be placed). Zeroes the barrier+task counters per launch. ─────────
203	template <OptId Opt>
204	cudaError_t launch_fused_decoder_megakernel(
205	        PersistentContext ctx, float* params, DecoderTokenCtx tok,
206	        float* grad, float lr, int step, FusedOptState st, cudaStream_t stream) {
207	    int dev = 0;
208	    cudaError_t err = cudaGetDevice(&dev);
209	    if (err != cudaSuccess) return err;
210	    int n_sms = 0;
211	    err = cudaDeviceGetAttribute(&n_sms, cudaDevAttrMultiProcessorCount, dev);
212	    if (err != cudaSuccess) return err;
213	
214	    int occ = 0;
215	    err = cudaOccupancyMaxActiveBlocksPerMultiprocessor(
216	        &occ, (const void*)&fused_decoder_megakernel<Opt>, 256,
217	        /*dynamicSMemBytes=*/0);
218	    if (err != cudaSuccess) return err;
219	    // Hang-freedom: at least one CTA per SM must be resident or the grid barrier
220	    // can never be satisfied. The L3-REAL kernel uses ≈42 KB static smem + a high
221	    // register count; if it cannot place one block/SM, REFUSE rather than hang.
222	    assert(occ >= 1 &&
223	           "fused_decoder_megakernel: 0 blocks/SM — GridBarrier would hang. The "
224	           "decoder smem (~42KB) + regs exceed one-block-per-SM occupancy; "
225	           "reduce footprint or fall back to the L1 per-op path.");
226	    if (occ < 1) return cudaErrorLaunchOutOfResources;
227	
228	    const unsigned launch_ctas = (unsigned)n_sms;
229	    ctx.n_ctas = launch_ctas;
230	
231	    if (ctx.g_arrived) { err = cudaMemsetAsync(ctx.g_arrived, 0, sizeof(unsigned), stream); if (err) return err; }
232	    if (ctx.g_generation) { err = cudaMemsetAsync(ctx.g_generation, 0, sizeof(unsigned), stream); if (err) return err; }
233	    if (ctx.g_next_task) { err = cudaMemsetAsync(ctx.g_next_task, 0, sizeof(int), stream); if (err) return err; }
234	
235	    dim3 grid(launch_ctas), block(256);
236	    fused_decoder_megakernel<Opt><<<grid, block, 0, stream>>>(
237	        ctx, params, tok, grad, lr, step, st);
238	    return cudaGetLastError();
239	}
