1930	void launch_csa_hca_bilevel_fwd_save(
1931	    torch::Tensor grad, torch::Tensor sharpness,
1932	    torch::Tensor input_proj_W, torch::Tensor input_proj_b,
1933	    torch::Tensor csa_q_W, torch::Tensor csa_k_W, torch::Tensor csa_v_W,
1934	    torch::Tensor csa_compress_w,
1935	    torch::Tensor csa_idx_DQ, torch::Tensor csa_idx_UQ, torch::Tensor csa_idx_K,
1936	    torch::Tensor csa_out_W,
1937	    torch::Tensor hca_q_W, torch::Tensor hca_k_W, torch::Tensor hca_v_W,
1938	    torch::Tensor hca_out_W,
1939	    int d_model, int num_heads,
1940	    int csa_compress, int csa_window, int csa_topk,
1941	    int hca_compress, int indexer_rank,
1942	    torch::Tensor csa_ctx_out, torch::Tensor hca_ctx_out,
1943	    torch::Tensor x_sorted, torch::Tensor sort_indices,
1944	    torch::Tensor csa_saved_denom, torch::Tensor csa_saved_sel_idx,
1945	    torch::Tensor csa_saved_probs,
1946	    torch::Tensor hca_saved_denom, torch::Tensor hca_saved_probs,
1947	    int checkpoint_interval)
1948	{
1949	    if (grad.numel() == 0) return;
1950	    (void)checkpoint_interval;
1951	    // gru_state placeholder (fwd_save does not carry GRU state across; the
1952	    // bilevel meta-loss re-derives gates in backward from gru_input + h_old).
1953	    auto h0 = torch::zeros({std::max(1, /*gru_hidden*/4)}, grad.options().dtype(torch::kFloat32));
1954	    auto S = sg2adj::bilevel_forward_save(
1955	        grad, sharpness, h0, input_proj_W, input_proj_b,
1956	        csa_q_W, csa_k_W, csa_v_W, csa_compress_w,
1957	        csa_idx_DQ, csa_idx_UQ, csa_idx_K, csa_out_W,
1958	        hca_q_W, hca_k_W, hca_v_W, hca_out_W,
1959	        torch::zeros({4, /*gru_in*/2 + 2 * d_model}, grad.options().dtype(torch::kFloat32)),
1960	        torch::zeros({4}, grad.options().dtype(torch::kFloat32)),
1961	        torch::zeros({4, 2 + 2 * d_model}, grad.options().dtype(torch::kFloat32)),
1962	        torch::zeros({4}, grad.options().dtype(torch::kFloat32)),
1963	        torch::zeros({4, 2 + 2 * d_model}, grad.options().dtype(torch::kFloat32)),
1964	        torch::zeros({4}, grad.options().dtype(torch::kFloat32)),
1965	        d_model, num_heads, csa_compress, csa_window, csa_topk,
1966	        hca_compress, indexer_rank);
1967	    if (csa_ctx_out.defined() && csa_ctx_out.numel() > 0) csa_ctx_out.copy_(S.csa_ctx);
1968	    if (hca_ctx_out.defined() && hca_ctx_out.numel() > 0) hca_ctx_out.copy_(S.hca_ctx);
1969	    if (x_sorted.defined() && x_sorted.numel() > 0) x_sorted.copy_(S.x_sorted);
1970	    if (sort_indices.defined() && sort_indices.numel() > 0)
1971	        sort_indices.copy_(S.sort_idx.to(sort_indices.dtype()));
1972	    if (csa_saved_denom.defined() && csa_saved_denom.numel() > 0)
1973	        csa_saved_denom.copy_(S.csa_denom);
1974	    if (csa_saved_sel_idx.defined() && csa_saved_sel_idx.numel() > 0)
1975	        csa_saved_sel_idx.copy_(S.csa_sel_idx.to(csa_saved_sel_idx.dtype()));
1976	    if (csa_saved_probs.defined() && csa_saved_probs.numel() > 0)
1977	        csa_saved_probs.copy_(S.csa_probs.reshape(csa_saved_probs.sizes()));
1978	    if (hca_saved_denom.defined() && hca_saved_denom.numel() > 0)
1979	        hca_saved_denom.copy_(S.hca_denom);
1980	    if (hca_saved_probs.defined() && hca_saved_probs.numel() > 0)
1981	        hca_saved_probs.copy_(S.hca_probs.reshape(hca_saved_probs.sizes()));
