1984	void launch_csa_hca_bilevel_fwd_save_batched(
1985	    std::vector<torch::Tensor> grads,
1986	    std::vector<torch::Tensor> sharpness_list,
1987	    torch::Tensor input_proj_W, torch::Tensor input_proj_b,
1988	    torch::Tensor csa_q_W, torch::Tensor csa_k_W, torch::Tensor csa_v_W,
1989	    torch::Tensor csa_compress_w,
1990	    torch::Tensor csa_idx_DQ, torch::Tensor csa_idx_UQ, torch::Tensor csa_idx_K,
1991	    torch::Tensor csa_out_W,
1992	    torch::Tensor hca_q_W, torch::Tensor hca_k_W, torch::Tensor hca_v_W,
1993	    torch::Tensor hca_out_W,
1994	    int d_model, int num_heads,
1995	    int csa_compress, int csa_window, int csa_topk,
1996	    int hca_compress, int indexer_rank,
1997	    torch::Tensor csa_ctx_out_packed, torch::Tensor hca_ctx_out_packed,
1998	    torch::Tensor x_sorted_packed, torch::Tensor offsets_t,
1999	    torch::Tensor sort_indices_packed,
2000	    torch::Tensor csa_saved_denom_packed, torch::Tensor csa_saved_sel_idx_packed,
2001	    torch::Tensor csa_saved_probs_packed,
2002	    torch::Tensor hca_saved_denom_packed, torch::Tensor hca_saved_probs_packed,
2003	    int checkpoint_interval)
2004	{
2005	    if (grads.empty()) return;
2006	    (void)checkpoint_interval;
2007	    // Packed layout: offsets_t[p]..offsets_t[p+1] delimit each param's rows.
2008	    auto offs = offsets_t.to(torch::kCPU).to(torch::kLong);
2009	    auto oacc = offs.accessor<int64_t, 1>();
2010	    const int P = (int)grads.size();
2011	    for (int p = 0; p < P; ++p) {
2012	        auto& g = grads[p];
2013	        if (!g.defined() || g.numel() == 0) continue;
2014	        const int64_t start = oacc[p];
2015	        const int64_t end   = oacc[p + 1];
2016	        const int64_t n = end - start;
2017	        if (n <= 0) continue;
2018	        auto h0 = torch::zeros({4}, g.options().dtype(torch::kFloat32));
2019	        auto S = sg2adj::bilevel_forward_save(
2020	            g, sharpness_list[p], h0, input_proj_W, input_proj_b,
2021	            csa_q_W, csa_k_W, csa_v_W, csa_compress_w,
2022	            csa_idx_DQ, csa_idx_UQ, csa_idx_K, csa_out_W,
2023	            hca_q_W, hca_k_W, hca_v_W, hca_out_W,
2024	            torch::zeros({4, 2 + 2 * d_model}, g.options().dtype(torch::kFloat32)),
2025	            torch::zeros({4}, g.options().dtype(torch::kFloat32)),
2026	            torch::zeros({4, 2 + 2 * d_model}, g.options().dtype(torch::kFloat32)),
2027	            torch::zeros({4}, g.options().dtype(torch::kFloat32)),
2028	            torch::zeros({4, 2 + 2 * d_model}, g.options().dtype(torch::kFloat32)),
2029	            torch::zeros({4}, g.options().dtype(torch::kFloat32)),
2030	            d_model, num_heads, csa_compress, csa_window, csa_topk,
2031	            hca_compress, indexer_rank);
2032	        if (csa_ctx_out_packed.defined() && csa_ctx_out_packed.numel() > 0)
2033	            csa_ctx_out_packed.narrow(0, start, n).copy_(S.csa_ctx);
2034	        if (hca_ctx_out_packed.defined() && hca_ctx_out_packed.numel() > 0)
2035	            hca_ctx_out_packed.narrow(0, start, n).copy_(S.hca_ctx);
2036	        if (x_sorted_packed.defined() && x_sorted_packed.numel() > 0)
2037	            x_sorted_packed.narrow(0, start, n).copy_(S.x_sorted);
2038	        if (sort_indices_packed.defined() && sort_indices_packed.numel() > 0)
2039	            sort_indices_packed.narrow(0, start, n).copy_(
2040	                S.sort_idx.to(sort_indices_packed.dtype()));
2041	    }
2042	    (void)csa_saved_denom_packed; (void)csa_saved_sel_idx_packed;
2043	    (void)csa_saved_probs_packed; (void)hca_saved_denom_packed;
2044	    (void)hca_saved_probs_packed;
2045	}
