2135	        ? gru_h_tilde.to(torch::kFloat32)
2136	        : torch::tanh(sg2adj::linear_fwd(xrh, gru_Wh));
2137	
2138	    std::vector<torch::Tensor> peer_Wq, prod_A, prod_B;
2139	    std::vector<torch::Tensor> dpeer_Wq, dprod_A, dprod_B;
2140	    const int64_t nph = peer_query_Ws.size(0);
2141	    for (int64_t h = 0; h < nph; ++h) {
2142	        peer_Wq.push_back(peer_query_Ws.index({h}).to(torch::kFloat32));
