2147	        dprod_B.push_back(torch::zeros_like(prod_B.back()));
2148	    }
2149	
2150	    sg2adj::bilevel_backward_driver(
2151	        d_smart_grad, rescale, S,
2152	        input_proj_W.to(torch::kFloat32),
2153	        csa_q_W.to(torch::kFloat32), csa_k_W.to(torch::kFloat32),
2154	        csa_v_W.to(torch::kFloat32), csa_compress_w.to(torch::kFloat32),
2155	        csa_idx_DQ.to(torch::kFloat32), csa_idx_UQ.to(torch::kFloat32),
2156	        csa_idx_K.to(torch::kFloat32), csa_out_W.to(torch::kFloat32),
2157	        hca_q_W.to(torch::kFloat32), hca_k_W.to(torch::kFloat32),
2158	        hca_v_W.to(torch::kFloat32), hca_out_W.to(torch::kFloat32),
2159	        gru_Wz.to(torch::kFloat32), gru_Wr.to(torch::kFloat32),
2160	        gru_Wh.to(torch::kFloat32),
2161	        peer_Wq, prod_A, prod_B,
2162	        expert_W1.to(torch::kFloat32),
